614→  const loadMessages = useCallback((msgs: ChatMessage[], outgoingConversationId?: string | null, incomingConversationId?: string | null) => {
615→    // Abort any ongoing stream before loading a different conversation
616→    if (abortRef.current) {
617→      abortRef.current.abort();
618→      abortRef.current = null;
619→    }
620→    if (flushTimerRef.current) {
621→      clearTimeout(flushTimerRef.current);
622→      flushTimerRef.current = null;
623→    }
624→
625→    // Check cache for incoming conversation — use cached messages if they
626→    // have more data than what the API returned (backend persistence may
627→    // not have completed yet when the user switches back quickly).
628→    let finalMsgs = msgs;
629→    if (incomingConversationId) {
630→      const cached = messagesCacheRef.current.get(incomingConversationId);
631→      if (cached && cached.length > msgs.length) {
632→        finalMsgs = cached;
633→      }
634→      // Clear used cache entry so stale data doesn't persist forever
635→      messagesCacheRef.current.delete(incomingConversationId);
636→    }
637→
638→    // Save current messages to cache before replacing them.
639→    // Uses functional setMessages to read the latest state without
640→    // needing `messages` in the dependency array.
641→    setMessages(prev => {
642→      if (outgoingConversationId && prev.length > 0) {
643→        // Flush any pending text buffer into the streaming assistant message
644→        const pendingText = textBufferRef.current;
645→        const aId = assistantIdRef.current;
646→
647→        // Build finalized segments including any unflushed text
648→        let finalSegments = [...segmentsRef.current];
649→        const pendingSegmentText = currentTextRef.current + pendingText;
650→        if (pendingSegmentText.trim()) {
651→          const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
652→          finalSegments.push({ type: segType as ContentSegment['type'], text: pendingSegmentText });
653→        }
654→
655→        const cleaned = prev.map(m => {
656→          if (m.id === aId && m.isStreaming) {
657→            return {
658→              ...m,
659→              content: m.content + pendingText,
660→              isStreaming: false,
661→              currentPhase: undefined,
662→              segments: finalSegments.length > 0 ? finalSegments : m.segments,
663→            };
664→          }
665→          return m;
666→        });
667→        messagesCacheRef.current.set(outgoingConversationId, cleaned);
668→      }
669→      return finalMsgs;
670→    });
671→
672→    setIsStreaming(false);
673→    textBufferRef.current = '';
674→    currentTextRef.current = '';
675→    segmentsRef.current = [];
676→    assistantIdRef.current = '';
677→    phaseRef.current = 'thinking';
678→    sessionIdRef.current = null;
679→    pendingHistoryRef.current = null;
680→  }, []);
681→
682→  const clearMessages = useCallback((outgoingConversationId?: string | null) => {
683→    if (abortRef.current) {
684→      abortRef.current.abort();
685→    }
686→    setMessages(prev => {
687→      if (outgoingConversationId && prev.length > 0) {
688→        const cleaned = prev.map(m =>
689→          m.isStreaming ? { ...m, isStreaming: false, currentPhase: undefined } : m
690→        );
691→        messagesCacheRef.current.set(outgoingConversationId, cleaned);
692→      }
693→      return [];
694→    });
695→    setIsStreaming(false);
696→    sessionIdRef.current = null;
697→    pendingHistoryRef.current = null;
698→  }, []);
699→
700→  return (
701→    <AgentContext.Provider
702→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, loadMessages, respondToQuestion }}
703→    >
704→      {children}
705→    </AgentContext.Provider>
706→  );
707→}
